<script>
window.addEventListener('beforeprint', () => {
    const height = Math.ceil(document.querySelector('.document').getBoundingClientRect().height * 25.4 / 96) + 6;
    let style = document.getElementById('thermal-page-size');
    if (!style) { style = document.createElement('style'); style.id = 'thermal-page-size'; document.head.append(style); }
    style.textContent = '@page { size: {{ (int)$format }}mm ' + Math.max(80,height) + 'mm; margin: 2mm; }';
});
